  /** The service it belongs to; null: every establishment */
  capability:
    | "dispensing"
    | "outsourced_diagnostics"
    | "laboratory"
    | "imaging"
    | "outpatient_procedures"
    | "inpatient"
    | "emergency_department"
    | "surgery"
    | "cssd"
    | "blood_transfusion"
    | "blood_center"
    | "maternity"
    | "home_visits"
    | "preventive_programmes"
    | null;
  /** The service is Active or Retiring (always true without one) */
  applies: boolean;
  /** The duty whose person must be someone else in the same case (null: no such rule, or its setting switched it off) */
  different_person_from: string | null;
  /** The database rule that enforces the different person */
