/** What the beds suggest by the PHC's bands; a person records the category on the licence (POST /establishment/changes with a profile). */
export interface CategorySuggestionOut {
  /** Null: no inpatient bed is set up (a clinic, or a hospital whose beds are not set up yet) */
  category: "I" | "IIA" | "IIB" | "IIC" | null;
  category_label: string | null;
  /** The beds set up: the active beds of the active wards, emergency wards left out */
  beds: number;
  /** The beds in use: those set up, less the ones out of service */
  operational: number;
  /** The beds set up but out of service now (a temporary closure) */
  out_of_service: number;
  /** Whether Haspataal holds the suggested category's framework (all five since 2026-10-14) */
  supported: boolean;
  /** One sentence to show next to the suggestion */
  note: string;
  wards: CountedWardOut[];
}

